const TodayFeature={id:"today",name:"Home",icon:"home",init(){},render:()=>'<div id="companion-root" class="comp-page"></div>',activate(){CompanionFeature.mount("companion-root")},deactivate(){CompanionFeature.unmount()},async getWeekEarnings(){const t=Utils.getStartOfWeek(),e=Utils.getEndOfWeek();return(await DB.getWeekStats(t.toISOString(),e.toISOString())).earnings},async getWeekSales(){const t=Utils.getStartOfWeek(),e=Utils.getEndOfWeek();return(await DB.getWeekStats(t.toISOString(),e.toISOString())).sales},async openEODModal(){const t=Utils.ukParts(),e=Utils.ukMidnightInstant(t.year,t.month,t.day),a=Utils.ukMidnightInstant(t.year,t.month,t.day+1);let n,o;try{[n,o]=await Promise.all([DB.getAppointmentsForDate(e.toISOString()),DB.getWeekStats(e.toISOString(),a.toISOString())])}catch(t){return console.error("End of Day records could not be read:",t),void Toast.show("Could not load today’s records. Please try again.","error")}const s=n.filter(t=>t.outcome).length,i=o.earnings,d=`\n      <div class="sheet-handle"></div>\n      <div class="sheet-header">\n        <h3>End of Day</h3>\n        <button class="btn btn-ghost btn-sm" data-action="App.closeModal"App.closeModal()">\n          <span class="material-symbols-rounded">close</span>\n        </button>\n      </div>\n      <div class="sheet-body">\n        <div class="grid-2 gap-12 mb-20" >\n          <div class="stat-card">\n            <div class="value">${Utils.formatCurrency(i)}</div>\n            <div class="label">Earned Today</div>\n          </div>\n          <div class="stat-card">\n            <div class="value">${s}/${n.length}</div>\n            <div class="label">Results Logged</div>\n          </div>\n        </div>\n\n        <div class="form-group">\n          <label>Anything to remember for tomorrow?</label>\n          <input type="text" class="input" id="eod-note" placeholder="e.g. Call back Mrs Jones about samples">\n        </div>\n\n        <button class="btn btn-primary btn-block" data-action="TodayFeature.completeEOD"TodayFeature.completeEOD()">\n          Done for Today <span class="material-symbols-rounded">check</span>\n        </button>\n      </div>\n    `;App.openModal(d)},async completeEOD(){const t=document.getElementById("eod-note"),e=t?t.value.trim():"";if(e)try{await DB.addCommunication({type:"note",content:`EOD note: ${e}`})}catch(t){}localStorage.setItem("advisoros_last_eod",Utils.formatDate(Utils.getToday(),"iso")),App.closeModal(),Toast.show("Day complete. See you tomorrow!","success"),App.navigate("today")}};App.registerFeature(TodayFeature);
